operations.exampleQuery:
query Pharma_assessEligibility {
  Pharma_assessEligibility(
    customerCode: ""
    origin: null
    productCode: ""
    storeCode: ""
  ) {
    dependents
    eligibilityAssessment
    registrationPolicy
    validationResult
  }
}

query Pharma_discountPrograms {
  Pharma_discountPrograms(
    origin: null
    storeCode: ""
  ) {
    allowedOrigins
    id
    name
    rules
    url
  }
}

query Pharma_prescriber {
  Pharma_prescriber(
    data: { council: null, registerNumber: 0, stateAbbr: "" }
  ) {
    errors
    message
    status
  }
}

query Pharma_retrieveTextTermsOptIn {
  Pharma_retrieveTextTermsOptIn(
    input: { CPF: "", Ean: "", Origem: 0 }
    origin: null
  ) {
    CodigoEnvio
    LinkTermos
    Mensagem
    Status
    TextoTermos
  }
}

query Pharma_verifyOptIn {
  Pharma_verifyOptIn(
    input: { CNPJ: "", CodCre: 0, CPF: "", EAN: "", Origem: 0 }
    origin: null
  ) {
    Mensagem
    OptInObrigatorio
    OptInRealizado
  }
}

query Prescription_prescriber {
  Prescription_prescriber(
    council: null
    enrollment: ""
    fu: ""
  ) {
    active
    council
    enrollment
    fu
    name
  }
}
